const DTC_MAP = {}; DTCS.forEach(d => { DTC_MAP[d.c] = d; d.al.forEach(a => { DTC_MAP[a] = d; }); });
const WHEELN = { C0035: 'trước trái', C0040: 'trước phải', C0045: 'sau trái', C0050: 'sau phải' };
function dtcInfo(code) {
  const c = String(code || '').toUpperCase().trim(), d = DTC_MAP[c]; if (!d) return null;
  const n = c.slice(-1), w = WHEELN[c] || 'trước trái';
  const f = s => String(s).replace(/\{n\}/g, n).replace(/\{w\}/g, w);
  return Object.assign({}, d, { code: c, d: f(d.d), en: f(d.en), cause: d.cause.map(f), eli: f(d.eli) });
}
